import{_ as a,a as e,c as r,ac as d}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"书单：作者、章节与阅读评析","description":"38 本书按四大模块整理，一书一页，介绍作者背景、目标读者、章节、阅读收获与客观评价。","frontmatter":{"title":"书单：作者、章节与阅读评析","description":"38 本书按四大模块整理，一书一页，介绍作者背景、目标读者、章节、阅读收获与客观评价。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单","summary":"38 本书按四大模块整理，一书一页，介绍作者背景、目标读者、章节、阅读收获与客观评价。","status":"active","related":[],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"life/personal/books/overview.md","filePath":"life/personal/books/overview.md"}'),i={name:"life/personal/books/overview.md"};function o(h,t,n,s,l,g){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="书单-作者、章节与阅读评析" tabindex="-1">书单：作者、章节与阅读评析 <a class="header-anchor" href="#书单-作者、章节与阅读评析" aria-label="Permalink to &quot;书单：作者、章节与阅读评析&quot;">​</a></h1><p>这份书单按学科与阅读目的整理，共 <strong>38 本</strong>，分为 <strong>4 个模块、10 个细分类</strong>。每本书只保留一个 Markdown 和一个主要归属；点击书名可以阅读作者背景、目标读者、章节导读、阅读收获与评价。</p><h2 id="怎样使用" tabindex="-1">怎样使用 <a class="header-anchor" href="#怎样使用" aria-label="Permalink to &quot;怎样使用&quot;">​</a></h2><ul><li><strong>找书</strong>：先选模块，再按细分领域进入单本书页。分类不依据书在照片中的位置。</li><li><strong>看章节</strong>：能确认版本的书提供原书章节导读；缺少作者、ISBN 或目录的书，明确标注为主题导读，核对版本后才能对应原书逐章阅读。</li><li><strong>看书评</strong>：各页的“读后感”是本站阅读评析，包含推荐理由、可实践的收获、缺点与阅读建议；其中的“个人收获”供读者对照自己的经历，不代表书单提供者的亲历。</li><li><strong>看摘抄</strong>：可核实的短引文注明出处；“本站阅读提炼”与原创代码切片会单独标明，不能当作原书金句或原书代码引用。</li><li><strong>辨别内容</strong>：小说页包含剧透提示；旧版技术书应结合当前官方文档理解版本差异。</li></ul><table tabindex="0"><thead><tr><th>模块</th><th>细分类</th><th>本数</th></tr></thead><tbody><tr><td><a href="#computing">计算机与软件工程</a></td><td>网络与操作系统、编程语言与开发框架、数据结构、算法与软件设计、架构、运维与云原生</td><td>21</td></tr><tr><td><a href="#languages">语言学习与出国考试</a></td><td>英语基础与商务、雅思备考专项</td><td>5</td></tr><tr><td><a href="#growth">个人成长、心理学与健康生活</a></td><td>心智与习惯、运动与健康</td><td>8</td></tr><tr><td><a href="#humanities">文学与人文社科</a></td><td>中外文学经典、随笔与散文</td><td>4</td></tr></tbody></table><h2 id="computing" tabindex="-1">计算机与软件工程 <a class="header-anchor" href="#computing" aria-label="Permalink to &quot;计算机与软件工程 {#computing}&quot;">​</a></h2><h3 id="networks-systems" tabindex="-1">网络与操作系统 <a class="header-anchor" href="#networks-systems" aria-label="Permalink to &quot;网络与操作系统 {#networks-systems}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./computing/network-foundations">《计算机网络基础教程（第3版）》</a></td><td>建立网络分层、通信协议与数据传输的整体认识。</td></tr><tr><td><a href="./computing/network-lab">《网络简介实验手册》</a></td><td>通过连通性、抓包和网络配置实验理解协议。</td></tr><tr><td><a href="./computing/internetworking">《网络互连技术》</a></td><td>理解路由、交换与不同网络之间的连接。</td></tr><tr><td><a href="./computing/network-technology">《网络技术教程》</a></td><td>建立网络设备、协议、组网与维护的知识框架。</td></tr><tr><td><a href="./computing/cisco-routing-switching-lab">《思科网络技术学院教程 路由和交换基础实验手册》</a></td><td>通过路由与交换实验训练配置和排障能力。</td></tr><tr><td><a href="./computing/network-principles">《计算机网络原理》</a></td><td>从协议机制与分层模型解释网络行为。</td></tr><tr><td><a href="./computing/rhel-65">《Red Hat Enterprise Linux 6.5 系统管理》</a></td><td>学习指定历史版本的 Linux 系统管理。</td></tr><tr><td><a href="./computing/linux-shell">《Linux命令行与shell脚本编程大全（第4版）》</a></td><td>从命令行操作进入脚本、文本处理与自动化。</td></tr></tbody></table><h3 id="languages-frameworks" tabindex="-1">编程语言与开发框架 <a class="header-anchor" href="#languages-frameworks" aria-label="Permalink to &quot;编程语言与开发框架 {#languages-frameworks}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./computing/c-programming">《C语言程序设计》</a></td><td>理解程序结构、内存、指针与基础编程。</td></tr><tr><td><a href="./computing/go-concurrency-microservices">《Go语言高并发与微服务实战》</a></td><td>连接 Go 并发机制与服务开发实践。</td></tr><tr><td><a href="./computing/spring-boot-2">《深入浅出Spring Boot 2.x》</a></td><td>学习 Spring Boot 2.x 应用开发及其生态。</td></tr><tr><td><a href="./computing/redis-design">《Redis设计与实现》</a></td><td>从数据结构、数据库到复制和集群理解 Redis。</td></tr><tr><td><a href="./computing/programming-rust">《Rust程序设计（第2版）》</a></td><td>学习所有权、类型、并发和系统编程。</td></tr></tbody></table><h3 id="algorithms-design" tabindex="-1">数据结构、算法与软件设计 <a class="header-anchor" href="#algorithms-design" aria-label="Permalink to &quot;数据结构、算法与软件设计 {#algorithms-design}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./computing/data-structures">《数据结构导论》</a></td><td>理解线性结构、树、图与基本查找排序。</td></tr><tr><td><a href="./computing/introduction-to-algorithms">《算法导论（原书第3版）》</a></td><td>系统学习算法设计、分析与正确性证明。</td></tr><tr><td><a href="./computing/comic-algorithms">《漫画算法》</a></td><td>以直观例子进入数据结构与算法。</td></tr><tr><td><a href="./computing/algorithms">《算法》</a></td><td>算法经典教材；具体作者与版本待核对。</td></tr><tr><td><a href="./computing/programmers-math">《程序员的数学》</a></td><td>用数学语言理解逻辑、计数、递归与复杂度。</td></tr><tr><td><a href="./computing/refactoring">《重构 改善既有代码的设计（第2版）》</a></td><td>在保持行为的前提下渐进改善代码设计。</td></tr></tbody></table><h3 id="cloud-native" tabindex="-1">架构、运维与云原生 <a class="header-anchor" href="#cloud-native" aria-label="Permalink to &quot;架构、运维与云原生 {#cloud-native}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./computing/istio">《云原生服务网格Istio》</a></td><td>理解服务流量治理、可观测性与安全。</td></tr><tr><td><a href="./computing/kubernetes-guide">《Kubernetes权威指南（第4版）》</a></td><td>理解容器编排、工作负载与集群运维。</td></tr></tbody></table><h2 id="languages" tabindex="-1">语言学习与出国考试 <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;语言学习与出国考试 {#languages}&quot;">​</a></h2><h3 id="english" tabindex="-1">英语基础与商务 <a class="header-anchor" href="#english" aria-label="Permalink to &quot;英语基础与商务 {#english}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./languages/new-concept-english-1">《新概念英语 智慧版 1》</a></td><td>以基础句型、听说读写练习建立英语能力。</td></tr><tr><td><a href="./languages/business-english">《实用商务英语》</a></td><td>练习职场沟通、商务邮件与工作场景表达。</td></tr></tbody></table><h3 id="ielts" tabindex="-1">雅思备考专项 <a class="header-anchor" href="#ielts" aria-label="Permalink to &quot;雅思备考专项 {#ielts}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./languages/ielts-reading">《雅思阅读真经总纲》</a></td><td>梳理阅读题型、定位与同义替换。</td></tr><tr><td><a href="./languages/ielts-vocabulary">《雅思词汇真经》</a></td><td>用主题、语境与复习建立词汇网络。</td></tr><tr><td><a href="./languages/ielts-speaking">《雅思口语真经总纲》</a></td><td>组织口语回答、展开观点与训练表达。</td></tr></tbody></table><h2 id="growth" tabindex="-1">个人成长、心理学与健康生活 <a class="header-anchor" href="#growth" aria-label="Permalink to &quot;个人成长、心理学与健康生活 {#growth}&quot;">​</a></h2><h3 id="mind-habits" tabindex="-1">心智与习惯 <a class="header-anchor" href="#mind-habits" aria-label="Permalink to &quot;心智与习惯 {#mind-habits}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./growth/seven-habits">《高效能人士的七个习惯》</a></td><td>从自我管理走向合作与持续更新。</td></tr><tr><td><a href="./growth/harvard-character">《哈佛大学性格自修课》</a></td><td>围绕性格、自我认知与行动进行反思。</td></tr><tr><td><a href="./growth/emotional-control">《当时忍住就好了》</a></td><td>观察情绪触发、冲动与回应选择。</td></tr><tr><td><a href="./growth/positive-discipline">《正面管教》</a></td><td>理解尊重、鼓励、界限与亲子合作。</td></tr><tr><td><a href="./growth/daily-notebook">《日知手帖》</a></td><td>将阅读、观察与日常反思留下记录。</td></tr></tbody></table><h3 id="movement-health" tabindex="-1">运动与健康 <a class="header-anchor" href="#movement-health" aria-label="Permalink to &quot;运动与健康 {#movement-health}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./growth/strength-training">《肌肉力量训练 彩色图谱》</a></td><td>从肌肉与动作关系理解力量训练。</td></tr><tr><td><a href="./growth/stretching">《精准拉伸》</a></td><td>理解拉伸目标、动作选择与身体感受。</td></tr><tr><td><a href="./growth/swimming">《从零开始学游泳》</a></td><td>从水性、呼吸与基础动作进入游泳练习。</td></tr></tbody></table><h2 id="humanities" tabindex="-1">文学与人文社科 <a class="header-anchor" href="#humanities" aria-label="Permalink to &quot;文学与人文社科 {#humanities}&quot;">​</a></h2><h3 id="literature" tabindex="-1">中外文学经典 <a class="header-anchor" href="#literature" aria-label="Permalink to &quot;中外文学经典 {#literature}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./humanities/one-hundred-years-of-solitude">《百年孤独》</a></td><td>从家族与城镇的历史阅读记忆、权力和孤独。</td></tr><tr><td><a href="./humanities/to-kill-a-mockingbird">《杀死一只知更鸟》</a></td><td>透过成长叙事思考偏见、正义与同理心。</td></tr><tr><td><a href="./humanities/one-sentence-ten-thousand">《一句顶一万句》</a></td><td>从说得着与说不着的关系理解孤独。</td></tr></tbody></table><h3 id="essays" tabindex="-1">随笔与散文 <a class="header-anchor" href="#essays" aria-label="Permalink to &quot;随笔与散文 {#essays}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书名</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="./humanities/sea-breeze-cinema">《海风电影院》</a></td><td>吴忠全的旅行随笔，记录岛屿、村庄与城市见闻。</td></tr></tbody></table><h2 id="阅读搭配建议" tabindex="-1">阅读搭配建议 <a class="header-anchor" href="#阅读搭配建议" aria-label="Permalink to &quot;阅读搭配建议&quot;">​</a></h2><ul><li><strong>算法路线</strong>：用《漫画算法》建立直觉，配合《数据结构导论》练实现，再用《算法导论》补证明与分析；《算法》的具体版本核对后再确定与前两本的搭配。</li><li><strong>服务开发路线</strong>：结合 Go 或 Spring Boot 的服务实践阅读《Redis设计与实现》，有部署基础后再进入 Kubernetes 和 Istio。</li><li><strong>英语路线</strong>：基础句型与日常表达不足时先读《新概念英语》；雅思阅读、词汇、口语可以围绕同一个主题交叉练习。</li><li><strong>成长与生活路线</strong>：把习惯、情绪和运动各选一个小目标，用《日知手帖》一类记录材料观察行动效果。</li><li><strong>文学路线</strong>：《杀死一只知更鸟》适合从成长和正义切入；《一句顶一万句》侧重人与人之间的语言和关系；《百年孤独》适合配合人物关系笔记慢读。</li></ul><h2 id="分类说明" tabindex="-1">分类说明 <a class="header-anchor" href="#分类说明" aria-label="Permalink to &quot;分类说明&quot;">​</a></h2><p>《Redis设计与实现》沿用本书单的“编程语言与开发框架”归属，阅读重点仍是数据库实现；《重构》放在“数据结构、算法与软件设计”，强调它讨论的是软件设计实践。文学模块沿用“文学与人文社科”的总名称。《海风电影院》经中信出版资料核对为吴忠全的旅行随笔，归入“随笔与散文”。</p><p><a href="/notes/">返回学习与生活</a></p>',34)])])}const b=a(i,[["render",o]]);export{c as __pageData,b as default};
